<?php
namespace App\Models; use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\BelongsTo; class ServiceOrderEvent extends Model { public $timestamps=false; const UPDATED_AT=null; protected $fillable=['actor_id','event','payload','created_at']; protected function casts():array{return ['payload'=>'array','created_at'=>'datetime'];} public function actor():BelongsTo{return $this->belongsTo(User::class,'actor_id');} }
